class Solution:
    def twoSum(self, nums: List[int], target: int) -> List[int]:
        # seen: 值 -> 下标。只存遍历过的数，保证查找时不会匹配到自己
        seen = {}
        for i, x in enumerate(nums):
            y = target - x          # 需要配对的另一个数
            if y in seen:           # 之前出现过 y，即找到答案
                return [seen[y], i]
            seen[x] = i             # 先查后存：当前 x 存入，留给后面的数配对
        return []                   # 题目保证有解，此行仅为语法完整性

problems.codeCpp:
class Solution {
public:
    vector<int> twoSum(vector<int>& nums, int target) {
        unordered_map<int, int> seen;        // 值 -> 下标
        for (int i = 0; i < (int)nums.size(); ++i) {
            int y = target - nums[i];        // 需要配对的另一个数
            auto it = seen.find(y);
            if (it != seen.end())            // 先查：y 已出现过
                return {it->second, i};
            seen[nums[i]] = i;               // 后存：留给后面的数配对
        }
        return {};
    }
};

