// ACM 模式：完整可运行程序（stdin -> stdout）
// 输入格式：
//   第一行：n（数组长度）
//   第二行：n 个整数（数组）
//   第三行：target
// 输出格式：一行两个下标，空格分隔
#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);   // 关闭同步，读入更快
    cin.tie(nullptr);

    int n;
    cin >> n;
    vector<int> nums(n);
    for (auto& x : nums) cin >> x;
    int target;
    cin >> target;

    unordered_map<int, int> seen;  // 值 -> 下标
    for (int i = 0; i < n; ++i) {
        int y = target - nums[i];
        auto it = seen.find(y);
        if (it != seen.end()) {    // 先查：命中即输出
            cout << it->second << " " << i << endl;
            return 0;
        }
        seen[nums[i]] = i;         // 后存
    }
    return 0;
}

problems.codeJava:
class Solution {
    public int[] twoSum(int[] nums, int target) {
        Map<Integer, Integer> seen = new HashMap<>();   // 值 -> 下标
        for (int i = 0; i < nums.length; i++) {
            int y = target - nums[i];                   // 需要配对的另一个数
            if (seen.containsKey(y))                    // 先查：y 已出现过
                return new int[]{seen.get(y), i};
            seen.put(nums[i], i);                       // 后存：留给后面的数配对
        }
        return new int[0];
    }
}

