/**
 * @param {number[]} nums
 * @param {number} target
 * @return {number[]}
 */
var twoSum = function (nums, target) {
  const seen = new Map();                // 值 -> 下标
  for (let i = 0; i < nums.length; i++) {
    const y = target - nums[i];          // 需要配对的另一个数
    if (seen.has(y)) return [seen.get(y), i]; // 先查：y 已出现过
    seen.set(nums[i], i);                // 后存：留给后面的数配对
  }
  return [];
};

