func twoSum(nums []int, target int) []int {
	seen := map[int]int{}            // 值 -> 下标
	for i, x := range nums {
		y := target - x              // 需要配对的另一个数
		if j, ok := seen[y]; ok {    // 先查：y 已出现过
			return []int{j, i}
		}
		seen[x] = i                  // 后存：留给后面的数配对
	}
	return []int{}
}
